async function main() {
  let updated = 0, notFound = [];
  for (const [name, description] of Object.entries(descs)) {
    const result = await prisma.product.updateMany({ where: { name }, data: { description } });
    if (result.count > 0) updated++;
    else notFound.push(name);
  }
  console.log("Atualizados:", updated, "/", Object.keys(descs).length);
  if (notFound.length) console.log("Nao encontrados:", notFound);
}
main().catch(console.error).finally(() => prisma.$disconnect());
